<?php namespace App\Controllers; use Vedairo\Http\Request;use Vedairo\Http\Response;use App\Models\User;use Vedairo\Auth\Auth;use Vedairo\Validation\Validator;use Vedairo\View; class AuthController {public function showLogin():string{return View::render('auth/login');}public function login(Request $r):never{$v=new Validator($r->input(),['email'=>'required|email','password'=>'required|min:6']);if(!$v->validate()){Response::json(['success'=>false,'errors'=>$v->errors()],422);}$u=User::byEmail((string)$r->input('email'));if(!$u||!password_verify((string)$r->input('password'),$u['password'])){Response::json(['success'=>false,'message'=>'Invalid credentials'],422);}unset($u['password']);$u['permissions']=\App\Models\User::permissions($u);Auth::login($u);redirect('/dashboard');}public function logout(Request $r):never{Auth::logout();redirect('/login');}}
